class Solution {
public:
    int maximumCount(vector<int>& nums) {
        int n = (int)nums.size();
        int neg = (int)(lower_bound(nums.begin(), nums.end(), 0) - nums.begin());
        int pos = n - (int)(upper_bound(nums.begin(), nums.end(), 0) - nums.begin());
        return max(neg, pos);
    }
};
